  var single=new ClassNode();single.version=c.version;single.access=c.access;single.name=c.name;single.superName=c.superName;single.interfaces=c.interfaces;single.methods.add(m);var computed=new ClassNode();new ClassReader(FreezeAcceptedMethods.bytes(single,true)).accept(computed,ClassReader.EXPAND_FRAMES);c.methods.set(c.methods.indexOf(m),computed.methods.get(0));bodies++;
